<script>
// ============================================================
// 打工人小账本 - 完整 JavaScript
// ============================================================

// ============ CONSTANTS ============
const CATEGORIES = {
  income: ['工资','奖金','兼职','理财收益','红包','报销','其他收入'],
  expense: ['餐饮','交通','购物','住房','娱乐','医疗','教育','人情','通讯','日用','服饰','其他']
};

const MONTHS = ['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];

// ============ DATA LAYER ============
const DB = {
  get(key, def) {
    try {
      const v = localStorage.getItem('wb_dgr_'+key);
      return v ? JSON.parse(v) : def;
    } catch(e) { return def; }
  },
  set(key, val) {
    localStorage.setItem('wb_dgr_'+key, JSON.stringify(val));
  },
  getRecords() { return this.get('records', []); },
  saveRecords(r) { this.set('records', r); },
  getSalary() { return this.get('salary', null); },
  saveSalary(s) { this.set('salary', s); },
  getGoals() { return this.get('goals', null); },
  saveGoals(g) { this.set('goals', g); },
  getSettings() { return this.get('settings', {demoCleared: false}); },
  saveSettings(s) { this.set('settings', s); }
};

// Current record type
let currentRecordType = 'expense';

// ============ DEMO DATA ============
function getDemoRecords() {
  const now = new Date();
  const d = (offset) => {
    const dt = new Date(now);
    dt.setDate(dt.getDate() - offset);
    return dt.toISOString().split('T')[0];
  };
  return [
    {id:'demo_1',date:d(0),amount:15,type:'expense',category:'餐饮',note:'午餐外卖',createdAt:Date.now()-1000,demo:true},
    {id:'demo_2',date:d(0),amount:48,type:'expense',category:'购物',note:'超市买菜',createdAt:Date.now()-2000,demo:true},
    {id:'demo_3',date:d(1),amount:6,type:'expense',category:'交通',note:'地铁通勤',createdAt:Date.now()-90000,demo:true},
    {id:'demo_4',date:d(2),amount:8500,type:'income',category:'工资',note:'7月工资',createdAt:Date.now()-180000,demo:true},
    {id:'demo_5',date:d(3),amount:28,type:'expense',category:'餐饮',note:'同事聚餐',createdAt:Date.now()-270000,demo:true},
  ];
}

function getDemoSalary() {
  return {
    monthlyTakeHome: 8500,
    payMonths: 12,
    workCosts: 1500,
    workDaysPerWeek: 5,
    onSiteDailyHours: 9,
    commuteDailyHours: 1.5,
    overtimeMonthlyHours: 20
  };
}

function getDemoGoals() {
  return {
    freedomTarget: 500000,
    currentSavings: 25000,
    monthlyContribution: 3000
  };
}

function getDemoSavings() {
  const now = new Date();
  const data = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const base = 10000 + (6 - i) * 3500 + (Math.random() - 0.5) * 2000;
    data.push({month: MONTHS[d.getMonth()] + ' ' + d.getFullYear(), savings: Math.round(base)});
  }
  return data;
}

function initDemoData() {
  const settings = DB.getSettings();
  if (settings.demoCleared) return;
  if (DB.getRecords().length > 0) return;
  DB.saveRecords(getDemoRecords());
  DB.saveSalary(getDemoSalary());
  DB.saveGoals(getDemoGoals());
  DB.set('savings', getDemoSavings());
}

// ============ CALCULATIONS ============
function calcHourlyWage(config) {
  if (!config) return null;
  const {
    monthlyTakeHome, payMonths, workCosts,
    workDaysPerWeek, onSiteDailyHours,
    commuteDailyHours, overtimeMonthlyHours
  } = config;

  const weeksPerMonth = 4.33;
  const annualTakeHome = monthlyTakeHome * payMonths;
  const annualCost = workCosts * 12;
  const annualOnSiteHours = payMonths * weeksPerMonth * workDaysPerWeek * onSiteDailyHours;
  const annualCommuteHours = payMonths * weeksPerMonth * workDaysPerWeek * commuteDailyHours;
  const annualOvertimeHours = overtimeMonthlyHours * payMonths;
  const totalHours = annualOnSiteHours + annualCommuteHours + annualOvertimeHours;

  if (totalHours <= 0) return null;

  const realHourlyWage = (annualTakeHome - annualCost) / totalHours;
  const nominalHourlyWage = annualTakeHome / annualOnSiteHours;

  return {
    realHourlyWage: Math.round(realHourlyWage * 100) / 100,
    nominalHourlyWage: Math.round(nominalHourlyWage * 100) / 100,
    perMinuteWage: Math.round(realHourlyWage / 60 * 100) / 100,
    annualTakeHome, annualCost, totalHours,
    annualOnSiteHours, annualCommuteHours, annualOvertimeHours,
    breakdown: {annualTakeHome, annualCost, annualOnSiteHours, annualCommuteHours, annualOvertimeHours, totalHours}
  };
}

function calcWorkEquivalent(amount, hourlyWage) {
  if (!hourlyWage || hourlyWage <= 0) return null;
  const totalMinutes = (amount / hourlyWage) * 60;
  const hours = Math.floor(totalMinutes / 60);
  const minutes = Math.round(totalMinutes % 60);
  return {hours, minutes, totalMinutes: Math.round(totalMinutes)};
}

function getMonthRecords(year, month) {
  const records = DB.getRecords();
  return records.filter(r => {
    const d = new Date(r.date + 'T00:00:00');
    return d.getFullYear() === year && d.getMonth() === month;
  });
}

function getMonthSummary() {
  const now = new Date();
  const records = getMonthRecords(now.getFullYear(), now.getMonth());
  let totalIncome = 0, totalExpense = 0;
  const expenseByCat = {};
  records.forEach(r => {
    if (r.type === 'income') totalIncome += r.amount;
    else {
      totalExpense += r.amount;
      expenseByCat[r.category] = (expenseByCat[r.category] || 0) + r.amount;
    }
  });

  // Fixed vs flexible expense classification
  const fixedCats = ['住房','通讯','交通'];
  const flexibleCats = ['餐饮','购物','娱乐','医疗','教育','人情','日用','服饰','其他'];
  let fixedExpense = 0, flexibleExpense = 0;
  for (const [cat, amt] of Object.entries(expenseByCat)) {
    if (fixedCats.includes(cat)) fixedExpense += amt;
    else flexibleExpense += amt;
  }

  return {totalIncome, totalExpense, fixedExpense, flexibleExpense, count: records.length, expenseByCat};
}

// ============ SCENARIO SIMULATION ============
function simulateScenarios(baseConfig) {
  if (!baseConfig) return [];
  const base = calcHourlyWage(baseConfig);
  if (!base) return [];

  const scenarios = [];

  // 1. 通勤变化
  const commuteUp = {...baseConfig, commuteDailyHours: baseConfig.commuteDailyHours + 0.5};
  const commuteDown = {...baseConfig, commuteDailyHours: Math.max(0, baseConfig.commuteDailyHours - 0.5)};
  const r1 = calcHourlyWage(commuteUp);
  const r2 = calcHourlyWage(commuteDown);
  if (r1) scenarios.push({label:'搬远一点（通勤+0.5h）',old:base.realHourlyWage,new:r1.realHourlyWage,icon:'🏠'});
  if (r2) scenarios.push({label:'搬到公司附近（通勤-0.5h）',old:base.realHourlyWage,new:r2.realHourlyWage,icon:'🏃'});

  // 2. 加班变化
  const otUp = {...baseConfig, overtimeMonthlyHours: baseConfig.overtimeMonthlyHours + 30};
  const otDown = {...baseConfig, overtimeMonthlyHours: Math.max(0, baseConfig.overtimeMonthlyHours - 10)};
  const r3 = calcHourlyWage(otUp);
  const r4 = calcHourlyWage(otDown);
  if (r3) scenarios.push({label:'加班增多（+30h/月）',old:base.realHourlyWage,new:r3.realHourlyWage,icon:'😰'});
  if (r4 && baseConfig.overtimeMonthlyHours >= 10) scenarios.push({label:'拒绝加班（-10h/月）',old:base.realHourlyWage,new:r4.realHourlyWage,icon:'😎'});

  // 3. 涨薪
  const raise = {...baseConfig, monthlyTakeHome: Math.round(baseConfig.monthlyTakeHome * 1.1)};
  const r5 = calcHourlyWage(raise);
  if (r5) scenarios.push({label:'涨薪 10%',old:base.realHourlyWage,new:r5.realHourlyWage,icon:'🎉'});

  // 4. 降低成本
  const costDown = {...baseConfig, workCosts: Math.round(baseConfig.workCosts * 0.7)};
  const r6 = calcHourlyWage(costDown);
  if (r6) scenarios.push({label:'降低工作成本 30%',old:base.realHourlyWage,new:r6.realHourlyWage,icon:'💡'});

  return scenarios;
}

// ============ RENDER: HOME ============
function renderHome() {
  const records = DB.getRecords();
  const settings = DB.getSettings();
  const summary = getMonthSummary();

