// ============ SAVINGS CHART (SVG) ============
function renderSavingsChart() {
  const svg = document.getElementById('savingsChart');
  const data = DB.get('savings', getDemoSavings());
  if (data.length === 0) {
    svg.innerHTML = '<text x="400" y="110" text-anchor="middle" fill="#9E9E9E" font-size="14">暂无存款数据</text>';
    return;
  }

  const W = 800, H = 200, PAD_L = 60, PAD_R = 20, PAD_T = 20, PAD_B = 30;
  const chartW = W - PAD_L - PAD_R;
  const chartH = H - PAD_T - PAD_B;

  const values = data.map(d => d.savings);
  const minV = Math.min(...values) * 0.9;
  const maxV = Math.max(...values) * 1.1;
  const range = maxV - minV || 1;

  const xScale = i => PAD_L + (i / Math.max(data.length - 1, 1)) * chartW;
  const yScale = v => PAD_T + chartH - ((v - minV) / range) * chartH;

  let pathD = '';
  data.forEach((d, i) => {
    const x = xScale(i), y = yScale(d.savings);
    pathD += (i === 0 ? 'M' : 'L') + x + ',' + y;
  });

  // Area fill
  const areaD = pathD + ' L' + xScale(data.length-1) + ',' + (PAD_T + chartH) + ' L' + PAD_L + ',' + (PAD_T + chartH) + ' Z';

  let dots = data.map((d, i) => {
    const x = xScale(i), y = yScale(d.savings);
    return `<circle cx="${x}" cy="${y}" r="4" fill="var(--mint)" stroke="white" stroke-width="2"/>`;
  }).join('');

  let labels = data.map((d, i) => {
    const x = xScale(i);
    return `<text x="${x}" y="${H - 8}" text-anchor="middle" font-size="10" fill="var(--text-light)">${d.month.split(' ')[0]}</text>`;
  }).join('');

  // Y-axis labels (2 ticks)
  let yLabels = '';
  for (let i = 0; i <= 2; i++) {
    const v = minV + (range / 2) * i;
    const y = yScale(v);
    yLabels += `<text x="${PAD_L - 8}" y="${y + 4}" text-anchor="end" font-size="9" fill="var(--text-light)">${(v/1000).toFixed(0)}k</text>`;
    yLabels += `<line x1="${PAD_L}" y1="${y}" x2="${W-PAD_R}" y2="${y}" stroke="var(--border)" stroke-width="0.5" stroke-dasharray="4 4"/>`;
  }

  svg.innerHTML = `
    <defs>
      <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#7EC8A4" stop-opacity="0.25"/>
        <stop offset="100%" stop-color="#7EC8A4" stop-opacity="0.02"/>
      </linearGradient>
    </defs>
    ${yLabels}
    <path d="${areaD}" fill="url(#areaGrad)"/>
    <path d="${pathD}" fill="none" stroke="var(--mint)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
    ${dots}
    ${labels}
  `;
}

