function renderSalary() {
  const config = DB.getSalary();
  if (config) {
    document.getElementById('salMonthly').value = config.monthlyTakeHome;
    document.getElementById('salMonths').value = config.payMonths;
    document.getElementById('salCost').value = config.workCosts;
    document.getElementById('salDays').value = config.workDaysPerWeek;
    document.getElementById('salOnSite').value = config.onSiteDailyHours;
    document.getElementById('salCommute').value = config.commuteDailyHours;
    document.getElementById('salOvertime').value = config.overtimeMonthlyHours;
    displayFormula(config);
  }
