function calcAndSaveSalary() {
  const config = {
    monthlyTakeHome: parseFloat(document.getElementById('salMonthly').value) || 0,
    payMonths: parseInt(document.getElementById('salMonths').value) || 12,
    workCosts: parseFloat(document.getElementById('salCost').value) || 0,
    workDaysPerWeek: parseInt(document.getElementById('salDays').value) || 5,
    onSiteDailyHours: parseFloat(document.getElementById('salOnSite').value) || 8,
    commuteDailyHours: parseFloat(document.getElementById('salCommute').value) || 0,
    overtimeMonthlyHours: parseInt(document.getElementById('salOvertime').value) || 0
  };

  if (config.monthlyTakeHome <= 0) { showToast('请填写月薪', 'error'); return; }
  if (config.onSiteDailyHours <= 0) { showToast('请填写每日在场时间', 'error'); return; }

  DB.saveSalary(config);
  displayFormula(config);
  showToast('时薪计算完成 ✓', 'success');
  renderGoals();
}

function displayFormula(config) {
  const result = calcHourlyWage(config);
  if (!result) return;
  const box = document.getElementById('formulaBox');
  box.style.display = 'block';
  const fmt = n => n.toLocaleString();
  const fmtH = n => Math.round(n).toLocaleString();

  box.innerHTML = `
    <div style="font-weight:700;margin-bottom:8px">📐 计算过程</div>
    <div>年收入 = <span class="var">${fmt(config.monthlyTakeHome)}</span> × <span class="var">${config.payMonths}</span> = ¥${fmt(result.annualTakeHome)}</div>
    <div>年工作成本 = <span class="var">${fmt(config.workCosts)}</span> × 12 = ¥${fmt(result.annualCost)}</div>
    <div>年在场时间 = <span class="var">${config.payMonths}</span> × 4.33 × <span class="var">${config.workDaysPerWeek}</span> × <span class="var">${config.onSiteDailyHours}</span> = ${fmtH(result.annualOnSiteHours)} h</div>
    <div>年通勤时间 = <span class="var">${config.payMonths}</span> × 4.33 × <span class="var">${config.workDaysPerWeek}</span> × <span class="var">${config.commuteDailyHours}</span> = ${fmtH(result.annualCommuteHours)} h</div>
    <div>年加班时间 = <span class="var">${config.overtimeMonthlyHours}</span> × <span class="var">${config.payMonths}</span> = ${fmtH(result.annualOvertimeHours)} h</div>
    <div style="margin-top:4px">总投入时间 = ${fmtH(result.totalHours)} 小时/年</div>
    <div class="result">
      真实时薪 = (¥${fmt(result.annualTakeHome)} - ¥${fmt(result.annualCost)}) ÷ ${fmtH(result.totalHours)} h<br>
      = <span class="big">¥${result.realHourlyWage.toFixed(2)}</span> / 小时<br>
      <span style="font-size:13px;color:var(--text-secondary)">（每分钟 ≈ ¥${result.perMinuteWage} | 账面时薪 ≈ ¥${result.nominalHourlyWage.toFixed(2)}）</span>
    </div>
  `;
}

// ============ RENDER: GOALS ============
function renderGoals() {
  const goals = DB.getGoals();
  if (goals) {
    document.getElementById('goalTarget').value = goals.freedomTarget;
    document.getElementById('goalCurrent').value = goals.currentSavings;
    document.getElementById('goalMonthly').value = goals.monthlyContribution;
    updateGoalDisplay(goals);
  }
  renderScenarios();
}

function saveGoals() {
  const goals = {
    freedomTarget: parseFloat(document.getElementById('goalTarget').value) || 500000,
    currentSavings: parseFloat(document.getElementById('goalCurrent').value) || 0,
    monthlyContribution: parseFloat(document.getElementById('goalMonthly').value) || 0
  };
  DB.saveGoals(goals);
  updateGoalDisplay(goals);
  showToast('目标已保存 ✓', 'success');
}

function updateGoalDisplay(goals) {
  const pct = goals.freedomTarget > 0 ? Math.min(100, Math.round(goals.currentSavings / goals.freedomTarget * 100)) : 0;
  document.getElementById('goalBar').style.width = pct + '%';
  document.getElementById('goalPercent').textContent = pct + '%';

  const circumference = 2 * Math.PI * 32;
  document.getElementById('goalRingFill').setAttribute('stroke-dasharray', (circumference * pct / 100) + ' ' + circumference);

  // ETA
  if (goals.monthlyContribution > 0 && goals.currentSavings < goals.freedomTarget) {
    const monthsLeft = Math.ceil((goals.freedomTarget - goals.currentSavings) / goals.monthlyContribution);
    const now = new Date();
    const eta = new Date(now.getFullYear(), now.getMonth() + monthsLeft, 1);
    document.getElementById('goalETA').textContent = `${eta.getFullYear()}年${eta.getMonth()+1}月（约${monthsLeft}个月）`;
  } else if (goals.currentSavings >= goals.freedomTarget) {
    document.getElementById('goalETA').textContent = '🎉 已达成！';
  } else {
    document.getElementById('goalETA').textContent = '请设置月存款额';
  }

  // Safety cushion
  const summary = getMonthSummary();
  const monthlyExpense = summary.totalExpense || (goals.monthlyContribution * 2);
  const safetyMonths = monthlyExpense > 0 ? Math.floor(goals.currentSavings / monthlyExpense) : 0;
  document.getElementById('safetyInfo').textContent = `当前存款可支撑 ${safetyMonths} 个月（月支出约 ¥${monthlyExpense.toLocaleString()}）`;
}

function renderScenarios() {
  const config = DB.getSalary();
  const container = document.getElementById('scenarioContainer');
  if (!config) {
    container.innerHTML = '<div class="empty-state"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg><p>请先在「真实时薪」页面设置并计算时薪</p></div>';
    return;
  }

  const base = calcHourlyWage(config);
  if (!base) return;

  const scenarios = simulateScenarios(config);
  container.innerHTML = `
    <div style="text-align:center;margin-bottom:16px">
      <span style="font-size:13px;color:var(--text-secondary)">当前真实时薪：</span>
      <span style="font-size:24px;font-weight:700;color:var(--mint-dark)">¥${base.realHourlyWage.toFixed(2)}/h</span>
    </div>
    ${scenarios.map(s => {
      const diff = s.new - s.old;
      const sign = diff >= 0 ? '+' : '';
      const color = diff >= 0 ? 'var(--income)' : 'var(--expense)';
      return `<div class="scenario-card">
        <div class="title">${s.icon} ${s.label}</div>
        <div class="compare">
          <span class="old">¥${s.old.toFixed(2)}/h</span>
          <span class="arrow">→</span>
          <span class="new" style="color:${color}">¥${s.new.toFixed(2)}/h (${sign}${diff.toFixed(2)})</span>
        </div>
      </div>`;
    }).join('')}
    <div style="font-size:12px;color:var(--text-light);text-align:center;margin-top:8px">
      💡 数据仅供对比参考，实际情况可能更复杂
    </div>
  `;
}

// ============ ADD RECORD ============
function addRecord() {
  const amount = parseFloat(document.getElementById('recordAmount').value);
  if (!amount || amount <= 0) { showToast('请输入金额', 'error'); return; }

  const record = {
    id: 'rec_' + Date.now(),
    date: document.getElementById('recordDate').value,
    amount: Math.round(amount * 100) / 100,
    type: currentRecordType,
    category: document.getElementById('recordCategory').value,
    note: document.getElementById('recordNote').value.trim(),
    createdAt: Date.now()
  };

  const records = DB.getRecords();
  records.push(record);
  DB.saveRecords(records);

  // Update savings
  if (record.type === 'income') {
    updateSavingsData();
  }

  // Show work equivalent for expenses
  if (record.type === 'expense') {
    const salaryConfig = DB.getSalary();
    const hw = salaryConfig ? calcHourlyWage(salaryConfig) : null;
    if (hw) {
      const eq = calcWorkEquivalent(record.amount, hw.realHourlyWage);
      if (eq) {
        const toast = document.getElementById('workToast');
        document.getElementById('workHours').textContent = eq.hours + ' 小时 ' + eq.minutes + ' 分钟';
        toast.classList.add('show');
        setTimeout(() => toast.classList.remove('show'), 2500);
      }
    }
  }

  // Reset form
  document.getElementById('recordAmount').value = '';
  document.getElementById('recordNote').value = '';

  showToast(currentRecordType === 'income' ? '收入已记录 ✓' : '支出已记录 ✓', 'success');
  renderBookkeeping();
  renderHome();
}

// ============ SAVINGS DATA UPDATE ============
function updateSavingsData() {
  const now = new Date();
  const monthLabel = MONTHS[now.getMonth()];
  let savings = DB.get('savings', []);

  // Calculate total savings from all records
  const allRecords = DB.getRecords();
  let total = 0;
  allRecords.forEach(r => {
    if (r.type === 'income') total += r.amount;
    else total -= r.amount;
  });

  const existingIdx = savings.findIndex(s => s.month.startsWith(monthLabel));
  if (existingIdx >= 0) {
    savings[existingIdx].savings = Math.round(total);
  } else {
    savings.push({month: monthLabel + ' ' + now.getFullYear(), savings: Math.round(total)});
    if (savings.length > 12) savings = savings.slice(-12);
  }
  DB.set('savings', savings);
}

// ============ DATA TOOLS ============
function exportData() {
  const data = {
    version: 1,
    exportedAt: new Date().toISOString(),
    records: DB.getRecords(),
    salary: DB.getSalary(),
    goals: DB.getGoals(),
    savings: DB.get('savings', []),
    settings: DB.getSettings()
  };
  const blob = new Blob([JSON.stringify(data, null, 2)], {type: 'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = '打工人小账本_备份_' + new Date().toISOString().split('T')[0] + '.json';
  a.click();
  URL.revokeObjectURL(url);
  showToast('数据已导出 ✓', 'success');
}

function importData(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const data = JSON.parse(e.target.result);
      if (!data.records || !Array.isArray(data.records)) throw new Error('数据格式不正确');
      DB.saveRecords(data.records);
      if (data.salary) DB.saveSalary(data.salary);
      if (data.goals) DB.saveGoals(data.goals);
      if (data.savings) DB.set('savings', data.savings);
      if (data.settings) DB.saveSettings(data.settings);
      showToast(`成功导入 ${data.records.length} 条记录 ✓`, 'success');
      renderAll();
    } catch(err) {
      showToast('导入失败：文件格式不正确', 'error');
    }
  };
  reader.readAsText(file);
  event.target.value = '';
}

function confirmClearData() {
  document.getElementById('confirmModal').classList.add('show');
}

function closeModal() {
  document.getElementById('confirmModal').classList.remove('show');
}

function doClearData() {
  ['records','salary','goals','savings','settings'].forEach(k => localStorage.removeItem('wb_dgr_'+k));
  closeModal();
  showToast('所有数据已清空', 'info');
  renderAll();
}

function clearDemoData() {
  const records = DB.getRecords().filter(r => !r.demo);
  DB.saveRecords(records);
  const settings = DB.getSettings();
  settings.demoCleared = true;
  DB.saveSettings(settings);
  showToast('示例数据已清除 ✓', 'success');
  renderAll();
}

// ============ TOAST ============
let toastTimer;
function showToast(msg, type) {
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.className = 'toast ' + type + ' show';
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('show'), 2000);
}

// ============ TAB SWITCHING ============
function switchTab(tab) {
  // Update tab contents
  document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));
  document.getElementById('tab-' + tab).classList.add('active');

  // Update sidebar
  document.querySelectorAll('#sidebarNav button').forEach(b => b.classList.remove('active'));
  const sideBtn = document.querySelector(`#sidebarNav button[data-tab="${tab}"]`);
  if (sideBtn) sideBtn.classList.add('active');

  // Update bottom nav
  document.querySelectorAll('#bottomNav button').forEach(b => b.classList.remove('active'));
  const bottomBtn = document.querySelector(`#bottomNav button[data-tab="${tab}"]`);
  if (bottomBtn) bottomBtn.classList.add('active');

  // Re-render
  if (tab === 'home') renderHome();
  else if (tab === 'bookkeeping') renderBookkeeping();
  else if (tab === 'salary') renderSalary();
  else if (tab === 'goals') renderGoals();
}

function renderAll() {
  const activeTab = document.querySelector('.tab-content.active');
  if (!activeTab) return;
  const tabId = activeTab.id.replace('tab-', '');
  switchTab(tabId);
}

// ============ EVENT LISTENERS ============
function setupListeners() {
  // Sidebar nav
  document.querySelectorAll('#sidebarNav button').forEach(btn => {
    btn.addEventListener('click', () => switchTab(btn.dataset.tab));
  });

  // Bottom nav
  document.querySelectorAll('#bottomNav button').forEach(btn => {
    btn.addEventListener('click', () => switchTab(btn.dataset.tab));
  });

  // Enter to add record
  document.getElementById('recordAmount').addEventListener('keydown', e => {
    if (e.key === 'Enter') addRecord();
  });

  // Modal close on overlay click
  document.getElementById('confirmModal').addEventListener('click', function(e) {
    if (e.target === this) closeModal();
  });

  // Toast click to dismiss
  document.getElementById('toast').addEventListener('click', function() {
    this.classList.remove('show');
  });

  // Work toast click to dismiss
  document.getElementById('workToast').addEventListener('click', function() {
    this.classList.remove('show');
  });

  // Keyboard shortcut
  document.addEventListener('keydown', e => {
    if (e.ctrlKey || e.metaKey) {
      if (e.key === 's') { e.preventDefault(); exportData(); }
      if (e.key === '1') { e.preventDefault(); switchTab('home'); }
      if (e.key === '2') { e.preventDefault(); switchTab('bookkeeping'); }
      if (e.key === '3') { e.preventDefault(); switchTab('salary'); }
      if (e.key === '4') { e.preventDefault(); switchTab('goals'); }
    }
  });
}

// ============ INIT ============
function init() {
  initDemoData();
  setupListeners();
  renderHome();
  renderBookkeeping();
  renderSalary();
  renderGoals();
}

document.addEventListener('DOMContentLoaded', init);
</script>
</body>
</html>"}

